  const [step, setStep] = useState<'enter-aadhaar' | 'verify-otp'>('enter-aadhaar');
  const [aadhaarNumber, setAadhaarNumber] = useState('');
  const [otpValue, setOtpValue] = useState('');
  const [timer, setTimer] = useState(30);
